import {TRACKS,SCENARIOS,DELAYS,defaultPattern,validateRhythm,validateDemo,requireEmpty,createTaskBridge} from './core.js';
import {DrumEngine} from './audio.js';
const $=id=>document.getElementById(id);
let rhythm={pattern:defaultPattern(),bpm:100}, sound=false,paused=false,finishDemo=null,demoTimer=null,demoCompletion=null,elapsedTimer=null,startedAt=0,demoId=0;
try{const stored=localStorage.getItem('waitbeat.rhythm.v1');if(stored)rhythm=validateRhythm(JSON.parse(stored));}catch{$('save-state').textContent='Device storage is unavailable. Your pattern stays for this visit.';}
const cells=[];const grid=$('grid');
for(let row=0;row<4;row++){
  const name=document.createElement('div');name.className='row-name';name.style.setProperty('--row',String(row*2+1));name.style.setProperty('--small-row',String(row*4+1));name.style.setProperty('--track',TRACKS[row].color);const dot=document.createElement('span');dot.className='swatch';dot.ariaHidden='true';name.append(dot,document.createTextNode(TRACKS[row].name));grid.append(name);
  for(let step=0;step<16;step++){const b=document.createElement('button');b.className='step'+(step>=8?' second-half':'');b.type='button';b.style.setProperty('--track',TRACKS[row].color);b.style.setProperty('--row',String(row*2+1));b.style.setProperty('--col',String(step%8+2));b.style.setProperty('--small-col',String(step%4+2));b.style.setProperty('--small-row',String(row*4+Math.floor(step/4)+1));b.dataset.step=String(step+1);b.setAttribute('aria-label',`${TRACKS[row].name}, step ${step+1}`);b.setAttribute('aria-pressed',String(!!rhythm.pattern[row][step]));b.title=`${TRACKS[row].name} · ${step+1}`;b.addEventListener('click',()=>{rhythm.pattern[row][step]^=1;paint();save();});grid.append(b);cells.push({b,row,step});}
}
grid.append(document.createElement('span'));for(let i=0;i<16;i++){const n=document.createElement('span');n.className='beat-number';n.textContent=String(i+1);grid.append(n);}
function save(){try{localStorage.setItem('waitbeat.rhythm.v1',JSON.stringify(rhythm));$('save-state').textContent='Your pattern stays on this device.';}catch{$('save-state').textContent='Not saved to device. Your pattern stays for this visit.';}}
function paint(){for(const {b,row,step} of cells)b.setAttribute('aria-pressed',String(!!rhythm.pattern[row][step]));$('tempo').value=rhythm.bpm;$('bpm').textContent=`${rhythm.bpm} BPM`;}
const engine=new DrumEngine(()=>rhythm,step=>{for(const c of cells)c.b.classList.toggle('playhead',c.step===step);});
function notice(text){$('notice').textContent=text;}
function silence(){engine.stop();clearInterval(elapsedTimer);elapsedTimer=null;}
const answers={review:'Demo review complete.\n\nThe sample change adds a loading state but leaves the submit button enabled. Disable it during the request, restore it on failure, and test two fast clicks. Keep the error beside the action so it is easy to recover.\n\nThis is a prepared example response, not an AI analysis of uploaded code.',trip:'Demo plan complete.\n\nStart with a short walk, choose a quiet place to sit, and leave one hour unplanned. Bring water and check local opening times before you leave.\n\nThis is a prepared example, not a live itinerary or recommendation about a specific place.',name:'Demo ideas complete.\n\nSecond Life Workshop\nThe Fixing Table\nMend & Meet\n\nPick a name people can say easily and check availability before using it. These are prepared examples; availability has not been checked.'};
const bridge=createTaskBridge(state=>{
  const waiting=state.phase==='waiting';document.body.classList.toggle('running',waiting);for(const id of ['scenario','duration','start'])$(id).disabled=waiting;for(const id of ['resolve','cancel'])$(id).disabled=!waiting;$('pause').disabled=!waiting||!sound;
  if(waiting){$('answer').hidden=true;paused=false;$('pause').textContent='Pause loop';$('task-state').textContent='Working on the demo task…';$('loop-status').textContent=sound?'Make it yours. The answer can arrive at any time.':'Try the steps. Turn sound on whenever you want.';notice('Demo wait started. This task uses a simulated delay and a prepared answer.');}
  else{silence();clearTimeout(demoTimer);demoTimer=null;finishDemo=null;$('loop-status').textContent='Your rhythm stays. Nothing to finish.';$('answer').hidden=false;
    if(state.phase==='ready'){$('task-state').textContent='Answer ready · music stopped';$('answer-kind').textContent='DEMO RESPONSE';$('answer-title').textContent='Back to your answer.';$('answer-body').textContent=String(state.value);notice('Answer ready. Playback has stopped; your pattern is preserved.');}
    else if(state.phase==='cancelled'){$('task-state').textContent='Task cancelled · music stopped';$('answer-kind').textContent='CANCELLED';$('answer-title').textContent='You can leave a wait unfinished.';$('answer-body').textContent='The task was cancelled. No answer was generated. Your rhythm is ready for another run.';notice('Task cancelled. Playback stopped.');}
    else{$('task-state').textContent='Task failed · music stopped';$('answer-kind').textContent='TASK ERROR';$('answer-title').textContent='The task did not finish.';$('answer-body').textContent=state.error;notice('Task failed. Playback stopped. You can try again.');}
    $('answer-body').className='answer-body';if($('loom').contains(document.activeElement)||document.activeElement===$('cancel')||document.activeElement===$('resolve'))$('answer-title').focus({preventScroll:true});
  }
});
function startDemo(input){const {scenario,seconds}=validateDemo(input);if(bridge.getState().phase==='waiting')throw new Error('A demo is already running. Finish or cancel it first.');$('scenario').value=scenario;$('duration').value=String(seconds);startedAt=Date.now();demoId++;
  demoCompletion=bridge.start(signal=>new Promise((resolve,reject)=>{finishDemo=()=>resolve(answers[scenario]);demoTimer=setTimeout(finishDemo,seconds*1000);signal.addEventListener('abort',()=>{clearTimeout(demoTimer);finishDemo=null;reject(new Error('Cancelled'));},{once:true});}));
  elapsedTimer=setInterval(()=>{$('task-state').textContent=`Demo task running · ${Math.floor((Date.now()-startedAt)/1000)}s elapsed`;},1000);if(sound&&!document.hidden)engine.start();return readState();
}
function readState(){return {phase:bridge.getState().phase,bpm:rhythm.bpm,pattern:rhythm.pattern.map(r=>[...r]),soundEnabled:sound,playing:engine.active,simulated:true};}
async function chooseSound(){if(sound){sound=false;engine.stop();}else{try{await engine.enable();sound=true;if(bridge.getState().phase==='waiting'&&!document.hidden){paused=false;engine.start();}}catch(error){notice(error.message);return;}}$('sound').textContent=sound?'Sound on':'Sound off';$('sound').setAttribute('aria-pressed',String(sound));$('pause').disabled=bridge.getState().phase!=='waiting'||!sound;$('pause').textContent='Pause loop';}
$('sound').addEventListener('click',chooseSound);
$('start').addEventListener('click',async()=>{if(sound){try{await engine.enable();}catch(error){notice(error.message);}}try{startDemo({scenario:$('scenario').value,seconds:Number($('duration').value)});}catch(error){notice(error.message);}});
$('resolve').addEventListener('click',()=>finishDemo?.());$('cancel').addEventListener('click',()=>bridge.cancel());
$('pause').addEventListener('click',async()=>{if(bridge.getState().phase!=='waiting'||!sound)return;if(paused){const run=demoId;try{await engine.enable();if(run!==demoId||bridge.getState().phase!=='waiting'||!sound||document.hidden)return;engine.start();}catch(error){notice(error.message);return;}}else engine.stop();paused=!paused;$('pause').textContent=paused?'Resume loop':'Pause loop';});
$('tempo').addEventListener('input',()=>{rhythm.bpm=Number($('tempo').value);paint();save();});
$('clear').addEventListener('click',()=>{rhythm.pattern=TRACKS.map(()=>Array(16).fill(0));paint();save();notice('Pattern cleared. The current task keeps running.');});
$('shuffle').addEventListener('click',()=>{const shifts=[0,2,4,6];const shift=shifts[Math.floor(Math.random()*shifts.length)];rhythm.pattern=defaultPattern().map((r,row)=>r.map((_,i)=>r[(i+shift+row*2)%16]));paint();save();notice('A new groove is ready. Change any step to make it yours.');});
document.addEventListener('visibilitychange',()=>{if(document.hidden){engine.stop();if(bridge.getState().phase==='waiting'){paused=true;$('pause').textContent='Resume loop';notice('Sound paused while this page was hidden. The task continues.');}}});
const toolLife=new AbortController();window.addEventListener('pagehide',event=>{bridge.cancel();if(event.persisted)engine.stop();else{toolLife.abort();void engine.dispose();}});
paint();
const context=document.modelContext;
if(context?.registerTool){
  const empty={type:'object',properties:{},additionalProperties:false};const definitions=[
    {name:'read_waitbeat',description:'Read the rhythm and task state. No sound or task is started.',inputSchema:empty,annotations:{readOnlyHint:true},execute:input=>{requireEmpty(input);return readState();}},
    {name:'set_waitbeat_rhythm',description:'Replace the visible 4 by 16 drum pattern and tempo. Saves to this device when storage is available. Does not enable audio.',inputSchema:{type:'object',properties:{bpm:{type:'integer',minimum:70,maximum:140},pattern:{type:'array',minItems:4,maxItems:4,items:{type:'array',minItems:16,maxItems:16,items:{type:'integer',enum:[0,1]}}}},required:['bpm','pattern'],additionalProperties:false},annotations:{readOnlyHint:false},execute:input=>{rhythm=validateRhythm(input);paint();save();return readState();}},
    {name:'start_waitbeat_demo',description:'Start a simulated agent wait with a prepared response. No AI provider is called. Does not enable sound; audio stays at the user-selected setting.',inputSchema:{type:'object',properties:{scenario:{type:'string',enum:SCENARIOS},seconds:{type:'integer',enum:DELAYS}},required:['scenario','seconds'],additionalProperties:false},annotations:{readOnlyHint:false},execute:input=>startDemo(input)},
    {name:'finish_waitbeat_demo',description:'Resolve the currently running simulated task now and stop the loop. Fails when no demo is running.',inputSchema:empty,annotations:{readOnlyHint:false},execute:async input=>{requireEmpty(input);if(!finishDemo||bridge.getState().phase!=='waiting')throw new Error('There is no running demo to finish.');finishDemo();await demoCompletion;return readState();}},
  ];for(const definition of definitions){try{void Promise.resolve(context.registerTool(definition,{signal:toolLife.signal})).catch(()=>{});}catch{}}
}
